/* HTTP Range support. iOS Safari (and others) request <audio> media with "Range: bytes=…" and
   refuse a plain 200 answer to such a request, so cached audio would not play offline.
   rangeResponse() slices the full cached file into a 206 with Content-Range / Content-Length /
   Content-Type; an unsatisfiable range gets 416. Multi-range requests get the whole file (200). */
const MIME = { mp3: "audio/mpeg", m4a: "audio/mp4", mp4: "audio/mp4", aac: "audio/aac", wav: "audio/wav", ogg: "audio/ogg", oga: "audio/ogg", opus: "audio/ogg", webm: "audio/webm" };
function rangeResponse(rangeHeader, full, pathname) {
  return full.arrayBuffer().then(buf => {
    const len = buf.byteLength;
    const ext = (pathname.match(/\.([A-Za-z0-9]+)$/) || [])[1];
    let type = full.headers.get("Content-Type");
    if (!type || /^(application\/octet-stream|text\/plain)/i.test(type)) type = MIME[(ext || "").toLowerCase()] || type || "application/octet-stream";
    const m = /^bytes=(\d*)-(\d*)$/.exec((rangeHeader || "").trim());
    if (!m || (m[1] === "" && m[2] === "")) {
      if (/^bytes=.*,/.test(rangeHeader || "")) return new Response(buf, { status: 200, headers: { "Content-Type": type, "Content-Length": String(len), "Accept-Ranges": "bytes" } });
      return new Response(null, { status: 416, headers: { "Content-Range": "bytes */" + len } });
    }
    let start, end;
    if (m[1] === "") { const n = +m[2]; if (n === 0) start = len; else { start = Math.max(0, len - n); } end = len - 1; } // suffix: last n bytes
    else { start = +m[1]; end = m[2] === "" ? len - 1 : Math.min(+m[2], len - 1); }
    if (start >= len || start > end) return new Response(null, { status: 416, headers: { "Content-Range": "bytes */" + len } });
    return new Response(buf.slice(start, end + 1), { status: 206, headers: {
      "Content-Type": type, "Content-Length": String(end - start + 1),
      "Content-Range": "bytes " + start + "-" + end + "/" + len, "Accept-Ranges": "bytes" } });
  });
}

self.addEventListener("fetch", e => {
  const u = new URL(e.request.url);
  if (e.request.method !== "GET" || u.origin !== self.location.origin) return; // never touch cross-origin (TTS voices, external links)
  const range = e.request.headers.get("Range");
  if (range) {
    /* Look the file up by plain URL (a Range request never matches a stored entry reliably), fetch the WHOLE
       file once if it is not cached yet, store it, then answer with the requested slice. */
    e.respondWith(
      caches.match(u.href).then(hit => hit || fetch(u.href).then(net => {
        if (net && net.ok && net.status === 200) { const clone = net.clone(); caches.open(CACHE).then(c => c.put(u.href, clone)); }
        return net;
      })).then(full => (full && full.status === 200 ? rangeResponse(range, full, u.pathname) : full))
    );
    return;
  }
  /* S13: the app shell (navigations / orale.html) is network-first with cache fallback.
     Cache-first here permanently pinned installed users to the version they installed:
     the cached HTML re-registered its own old sw.js?v=..., so a new APP_VERSION on the
     server was never fetched and the version-aware cache retirement never triggered.
     Static assets stay cache-first for speed. Offline behavior is unchanged. */
  const shell = e.request.mode === "navigate" || u.pathname.endsWith("/orale.html") || u.pathname.endsWith("/");
  if (shell) {
    e.respondWith(
      fetch(e.request).then(net => {
        if (net && net.ok) { const clone = net.clone(); caches.open(CACHE).then(c => c.put(e.request, clone)); }
        return net;
      }).catch(() => caches.match(e.request).then(hit => hit || caches.match("./orale.html")))
    );
    return;
  }
  e.respondWith(
    caches.match(e.request).then(hit => hit || fetch(e.request).then(net => {
      if (net && net.ok) { const clone = net.clone(); caches.open(CACHE).then(c => c.put(e.request, clone)); }
      return net;
    })).catch(() => caches.match("./orale.html"))
  );
});
